    assign readback_array[5][11:6] = (decoded_reg_strb.LINE_WEIGHT_4 && !decoded_req_is_wr) ? field_storage.LINE_WEIGHT_4.W_1.value : '0;
    assign readback_array[5][17:12] = (decoded_reg_strb.LINE_WEIGHT_4 && !decoded_req_is_wr) ? field_storage.LINE_WEIGHT_4.W_2.value : '0;
    assign readback_array[5][23:18] = (decoded_reg_strb.LINE_WEIGHT_4 && !decoded_req_is_wr) ? field_storage.LINE_WEIGHT_4.W_3.value : '0;
    assign readback_array[5][29:24] = (decoded_reg_strb.LINE_WEIGHT_4 && !decoded_req_is_wr) ? field_storage.LINE_WEIGHT_4.W_4.value : '0;
    assign readback_array[5][31:30] = '0;

    // Reduce the array
    always_comb begin
        automatic logic [31:0] readback_data_var;
        readback_done = decoded_req & ~decoded_req_is_wr;
        readback_err = '0;
        readback_data_var = '0;
        for(int i=0; i<6; i++) readback_data_var |= readback_array[i];
        readback_data = readback_data_var;
    end

    assign cpuif_rd_ack = readback_done;
    assign cpuif_rd_data = readback_data;
    assign cpuif_rd_err = readback_err;
endmodule
